INSERT INTO people (id, display_name, gender, biography, created_at, updated_at) VALUES ('a7c12b12-3585-46be-b644-62c0a24b67ec', 'Esmail Masoudi', 'male', 'Son of Haj Mirza Agha Masoudi and brother of Robabeh Masoudi. The family history of the customs duty on gut records that it was Esmail who noticed the customs notice on a scrap of newspaper wrapped around vegetables and brought it to Ramazan Darabi, two days before the deadline.', '2026-08-27T08:57:30.986Z', '2026-08-27T08:57:30.986Z');
