INSERT INTO people (id, display_name, gender, biography, created_at, updated_at) VALUES ('6c10f55e-c176-4d3c-8297-715a2197adfa', 'Mahmoud Masoudi', 'male', 'Son of Haj Mirza Agha Masoudi and brother of Robabeh Masoudi, named in the family biography''s account of Ghassem Darabi.', '2026-08-27T08:57:30.986Z', '2026-08-27T08:57:30.986Z');
