INSERT INTO people (id, display_name, gender, biography, created_at, updated_at) VALUES ('0fb595ba-b155-48ca-a219-6ae79e26a1c5', 'Gholamreza Darabi', 'male', 'First son of Hossein Zehtab Darabi and Ategheh Khanom. He died of illness in childhood, and his birth certificate was given over to his younger brother Gholamhossein, who was known as Gholamreza from then on — the Gholam Reza Darabi of this tree is that brother.', '2026-08-27T08:57:30.986Z', '2026-08-27T08:57:30.986Z');
INSERT OR IGNORE INTO relationships (id, from_person_id, to_person_id, type, created_at) VALUES ('f6741587-c0b3-4189-bd8b-26f32ad34e7d', 'e2ff5ca0-38d1-4bf1-9c3f-ff60c016ecbd', '0fb595ba-b155-48ca-a219-6ae79e26a1c5', 'parent', '2026-08-27T08:57:30.986Z');
INSERT OR IGNORE INTO relationships (id, from_person_id, to_person_id, type, created_at) VALUES ('cef7e608-52eb-48a9-8b35-9ed56713e19e', '638fd64a-1647-4633-b59f-38cc7effc0dc', '0fb595ba-b155-48ca-a219-6ae79e26a1c5', 'parent', '2026-08-27T08:57:30.986Z');
UPDATE people SET biography = 'Generation 5 daughter of Mohammad Zehtab Darabi and Salmeh. Born about 1268 Solar Hijri in Qazvin. Described as composed, dignified, beautiful, and tall, noted for housekeeping, raising children, and devotion to family. She died in middle age. In her husband''s household she was called Mirza Baji.', updated_at = '2026-08-27T08:57:30.986Z' WHERE id = '660e6499-1a6e-4214-b532-33a428c79742' AND biography = 'Generation 5 daughter of Mohammad Zehtab Darabi and Salmeh. Born about 1268 Solar Hijri in Qazvin. Described as composed, dignified, beautiful, and tall, noted for housekeeping, raising children, and devotion to family. She died in middle age.';
UPDATE people SET biography = 'Generation 5, the youngest of the five children of Mohammad Zehtab Darabi and Salmeh. The family biography records that he died in his youth. He stands first from the left in the family photograph of about 1920.', updated_at = '2026-08-27T08:57:30.986Z' WHERE id = '9b32dea9-8c7c-41a1-9aa5-552816721199' AND biography IS NULL;
UPDATE people SET biography = 'Son of Hossein Zehtab Darabi and Ategheh Khanom, born Gholamhossein. After his elder brother Gholamreza died in childhood, the family biography records that the brother''s birth certificate was given over to him and he was known as Gholamreza from then on. He was among the first children of the family sent to school. Also recorded in the family archive as Gholamreza Darabi.', updated_at = '2026-08-27T08:57:30.986Z' WHERE id = '6e366ac3-d952-4ffa-8dcd-123b7eb03b3d' AND biography = 'Also recorded in the family archive as Gholamreza Darabi.';
UPDATE people SET biography = 'Eldest son of Fatemeh Darabi and Haj Ramazan Jaberian. He worked in the family partnership as bookkeeper of the factory and the slaughterhouse, and with his uncle Ghassem was one of the first two in the family to read and write, sent to night school by Ramazan Darabi. In the double wedding of about 1927 he was married to Ashraf in a match arranged the same evening — the family history records he learned of his own wedding two nights before it. He stands third from the left, a boy in white, in the family photograph of about 1920.', updated_at = '2026-08-27T08:57:30.986Z' WHERE id = 'ddd5b30f-dce9-440d-bf17-b99dd3ec9a35' AND biography IS NULL;
UPDATE people SET biography = 'Father of Robabeh Masoudi. The biography mentions a prior conflict between him and Hossein Zehtab Darabi that was later resolved when his daughter married Ghassem Darabi. He was head of the butchers'' guild in Qazvin. His children were Ebrahim, Esmail, Mahmoud, Fatemeh, Robabeh, and Masoumeh.', updated_at = '2026-08-27T08:57:30.986Z' WHERE id = 'b9a60325-2ac4-4f02-ab3b-05e4a182195f' AND biography = 'Father of Robabeh Masoudi. The biography mentions a prior conflict between him and Hossein Zehtab Darabi that was later resolved when his daughter married Ghassem Darabi.';
UPDATE people SET biography = 'Generation 4 ancestor, son of Haj Khalil. Born in 1235 Solar Hijri in Qazvin and died in 1318. A skilled and industrious maker of gut strings, he developed improved production methods and later worked with his sons in a family company and factory. The main branches of the family begin with his children. His first wife Salmeh died in middle age, and his children later chose a second wife for him, who remained at his side to the end of his life. The family biography records that he worked at the factory until the day before his death, and that he arranged his own funeral — the grave bought, the mosque spoken to, and the money for the ceremony left on the ledge of the room.', updated_at = '2026-08-27T08:57:30.986Z' WHERE id = 'c8a1f8a4-d83d-4638-8de4-ceb8246908cb' AND biography = 'Generation 4 ancestor, son of Haj Khalil. Born in 1235 Solar Hijri in Qazvin and died in 1318. A skilled and industrious maker of gut strings, he developed improved production methods and later worked with his sons in a family company and factory. The main branches of the family begin with his children.';
UPDATE people SET biography = 'Generation 5 son of Mohammad Zehtab Darabi and Salmeh. Born in 1282 Solar Hijri in Qazvin. He worked in the family factory from youth, became highly skilled in the gut trade, moved with his family to Tehran in 1326, became a successful merchant, established factories, and died in Farvardin 1358 at age 75 of a heart attack. With his nephew Asadollah he was one of the first two in the family to read and write, sent to night school by his brother Ramazan.', updated_at = '2026-08-27T08:57:30.986Z' WHERE id = 'ba4b61e3-4b59-4d8b-8e37-5733c2951d41' AND biography = 'Generation 5 son of Mohammad Zehtab Darabi and Salmeh. Born in 1282 Solar Hijri in Qazvin. He worked in the family factory from youth, became highly skilled in the gut trade, moved with his family to Tehran in 1326, became a successful merchant, established factories, and died in Farvardin 1358 at age 75 of a heart attack.';
UPDATE people SET biography = 'Generation 5 son of Mohammad Zehtab Darabi and Salmeh. Born about 1261 Solar Hijri in Qazvin and died in 1316 at age 55. He was described as small in build, quick, capable, kind, hospitable, and devoted to family. He traveled on pilgrimage to Karbala and survived a serious fall during quarantine in Iraq. In the family partnership he ran the company.', updated_at = '2026-08-27T08:57:30.986Z' WHERE id = 'e2ff5ca0-38d1-4bf1-9c3f-ff60c016ecbd' AND biography = 'Generation 5 son of Mohammad Zehtab Darabi and Salmeh. Born about 1261 Solar Hijri in Qazvin and died in 1316 at age 55. He was described as small in build, quick, capable, kind, hospitable, and devoted to family. He traveled on pilgrimage to Karbala and survived a serious fall during quarantine in Iraq.';
