INSERT INTO change_log (id, actor_email, kind, summary, payload_json, created_at) VALUES ('cdeb6f6f-0ace-462e-b834-859ca9def584', 'ramine@ramine.net', 'enrich_from_histories', 'Entered the facts the family histories state: 5 people added, 8 biographies corrected.', '{"entries":["+ Ebrahim Masoudi (male), child of Haj Mirza Agha Masoudi","+ Esmail Masoudi (male), child of Haj Mirza Agha Masoudi","+ Mahmoud Masoudi (male), child of Haj Mirza Agha Masoudi","+ Masoumeh Masoudi (female), child of Haj Mirza Agha Masoudi","+ Gholamreza Darabi (male), child of Hossein Zehtab Darabi + Ategheh Khanom","~ Fatemeh Darabi: added: In her husband''s household she was called Mirza Baji.","~ Abbas Darabi: biography written","~ Gholam Reza Darabi: biography written","~ Asadollah Jaberian: biography written","~ Haj Mirza Agha Masoudi: added: He was head of the butchers'' guild in Qazvin. His children were Ebrahi","~ Mohammad Zehtab Darabi: added: His first wife Salmeh died in middle age, and his children later chose","~ Ghassem Darabi: added: With his nephew Asadollah he was one of the first two in the family to","~ Hossein Zehtab Darabi: added: In the family partnership he ran the company.","* linked Esmail Masoudi to \"The customs duty on gut\"","* linked Gholamreza Darabi to \"Hossein Zehtab (Darabi), fifth generation\"","* linked Gholam Reza Darabi to \"Hossein Zehtab (Darabi), fifth generation\"","* linked Ebrahim Masoudi to \"Ghassem Darabi, fifth generation\"","* linked Esmail Masoudi to \"Ghassem Darabi, fifth generation\"","* linked Mahmoud Masoudi to \"Ghassem Darabi, fifth generation\"","* linked Masoumeh Masoudi to \"Ghassem Darabi, fifth generation\"","* linked Gholam Reza Darabi to \"Ghassem and Asadollah, the first in the family to read and write\"","* linked Aghdas Darabi to \"Ghassem and Asadollah, the first in the family to read and write\""]}', '2026-08-27T08:57:30.986Z');
